const PORTION = 10; // Kanäle je Portion (talents_plattform_abruf_liste p_anzahl)
// Lauf starten (Stefan 18.10.2026): Portionen der fälligen Kanäle nacheinander abarbeiten (talents_abruf_liste mit p_anzahl).
