const TAG = /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/;
const out = [];
for (const k of Array.isArray(r.kanaele) ? r.kanaele : []) {
  const id = Number(k && k.kanal_id);
  if (!(id > 0) || erledigt.has(id)) continue;
  const j = { start: true, kanal_id: id, plattform: PL, extern_id: String(k.extern_id || ''), seite_id: String(k.seite_id || ''),
    api: String(k.api || ''), data_api: String(k.data_api || ''), von: String(k.von || ''), bis: String(k.bis || ''), tag: String(k.tag || ''),
    tage: (Array.isArray(k.tage) ? k.tage : []).filter(t => t && TAG.test(String(t.tag)) && Number(t.since) > 0 && Number(t.until) > Number(t.since))
      .map(t => ({ tag: String(t.tag), since: Number(t.since), until: Number(t.until) })),
    seit_unix: Number(k.seit_unix) > 0 ? Number(k.seit_unix) : null,
